const initialTab=():Tab=>{const value=new URLSearchParams(location.search).get('tab')||location.hash.slice(1);return value in tabs?value as Tab:'start';};
const short=(value:string)=>value.length>16?value.slice(0,6)+'…'+value.slice(-4):value;
const editionNumber=(value:number)=>String(value).padStart(3,'0');
const same=(a?:string|null,b?:string|null)=>Boolean(a&&b&&a.toLowerCase()===b.toLowerCase());
