const sessionSuppressed=()=>{try{return sessionStorage.getItem('upic-staging-signed-out')==='1';}catch{return false;}};
function suppressSession(value:boolean){try{if(value)sessionStorage.setItem('upic-staging-signed-out','1');else sessionStorage.removeItem('upic-staging-signed-out');}catch{/* A private wallet browser may disable session storage. */}}
function deploymentReady(config?:Config){if(!config)return false;const d=config.deployment;return (d.mode==='local'?d.chainId===31337:d.mode==='testnet'&&[46630,421614].includes(d.chainId))&&[d.factory,d.upic,d.marketplace,d.vault].every(a=>isAddress(a)&&a.toLowerCase()!==zeroAddress);}
function friendlyError(error:unknown){const text=errorText(error);const messages:Record<string,string>={
 'session-required':'Your sign-in has expired. Connect your wallet again.',unauthorized:'Connect your wallet to continue.',
 'insufficient-upic':'Your wallet needs more test UPIC. Use the token faucet in Your wallet.',
 'insufficient-mint-balance':'Your wallet needs enough test ETH for this mint and gas. Open Your wallet to request test gas.',
 'preview-only-asset':'This asset is available for previews. Collection creation is not enabled for its verification policy yet.',
 'verification-pending':'Verification is still running. Check preparation again in a moment.',
 'collection-sold-out':'All editions in this collection have been minted.',
 'collection-exists':'This collection already exists. Open Collections to mint an edition.',
 'stage-changed-reprepare':'The artwork has evolved. Prepare it again to use the latest verified stage.',
 'faucet-unconfigured':'The gas faucet is not configured for this staging deployment.',
 'faucet-empty':'The test gas faucet needs a refill. Try again after the staging operator funds it.',
 'faucet-rate-limited':'You have requested gas recently. Try again after the faucet cooldown.',
 'deployment-unconfigured':'Staging contracts are not configured yet. You can still explore the instrument and labs.',
};return messages[text]||text;}
function amount(value:string){if(!/^\d+(\.\d{1,18})?$/.test(value.trim()))throw Error('Enter a positive amount with up to 18 decimal places.');const parsed=parseEther(value.trim());if(parsed<=0n)throw Error('Enter an amount greater than zero.');return parsed;}

