 const [note,setNote]=useState(''),[noteKind,setNoteKind]=useState<'info'|'error'|'success'>('info'),[busy,setBusy]=useState(false),[tab,setTab]=useState<Tab>(initialTab),[form,setForm]=useState<FormState>();
