 function openEdition(edition:Edition){setNFT(edition);history.pushState(null,'','/nft/'+edition.collection+'/'+edition.edition);setRoutePath(location.pathname);window.scrollTo({top:0,behavior:'auto'});}
 async function readSetup(){const result=await Promise.allSettled([api<Config>('/v1/config'),api<StagingStatus>('/v1/status')]);const c=result[0],s=result[1];if(c.status==='fulfilled'){setConfig(c.value);setSetupError(deploymentReady(c.value)?'':'A supported test network and deployed contracts are needed before wallet actions are available.');}else{setConfig(undefined);setSetupError(friendlyError(c.reason));}if(s.status==='fulfilled')setStatus(s.value);else setStatus(undefined);}
 async function loadOwned(account:Address){try{const rows=await api<Edition[]>('/v1/wallet/'+account);if(same(walletRef.current,account)){setOwned(rows);setOwnedError('');}}catch(e){if(same(walletRef.current,account))setOwnedError(friendlyError(e));}}
 async function refresh(){setLoading(true);const results=await Promise.allSettled([api<Collection[]>('/v1/collections'),api<Asset[]>('/v1/assets'),api<Order[]>('/v1/orders')]);const [c,a,o]=results;const errors:string[]=[];if(c.status==='fulfilled')setCollections(c.value);else errors.push('Collections: '+friendlyError(c.reason));if(a.status==='fulfilled')setAssets(a.value);else errors.push('Assets: '+friendlyError(a.reason));if(o.status==='fulfilled')setOrders(o.value);else errors.push('Listings: '+friendlyError(o.reason));setDataError(errors.join(' '));setLoading(false);setDataRevision(n=>n+1);if(walletRef.current)await loadOwned(walletRef.current);}
 useEffect(()=>{void readSetup();void refresh();},[]);
 useEffect(()=>{function route(){setTab(initialTab());setRoutePath(location.pathname);setNFT(undefined);}window.addEventListener('popstate',route);window.addEventListener('hashchange',route);return()=>{window.removeEventListener('popstate',route);window.removeEventListener('hashchange',route);};},[]);
 useEffect(()=>{let cancelled=false;const route=/\/nft\/(0x[a-fA-F0-9]+)\/(\d+)\/?$/.exec(routePath);if(!route||!collections.length)return;const found=collections.find(c=>same(c.address,route[1])||same(c.asset_key,route[1]));if(!found){report('This collection is not available in this staging deployment.','error');return;}api<{editions:Edition[]}>('/v1/collections/'+found.address).then(v=>{if(cancelled||location.pathname!==routePath)return;const e=v.editions.find(e=>e.edition===Number(route[2]));setSelected(found);setEditions(v.editions);if(e)setNFT(e);else report('This edition has not been indexed yet. Refresh after its mint confirms.','info');}).catch(e=>{if(!cancelled)report(friendlyError(e),'error');});return()=>{cancelled=true;};},[collections,routePath]);
 useEffect(()=>{if(!selected)return;let cancelled=false;setEditions([]);setEditionError('');setPrice(undefined);setPriceError('');setUpkeep(undefined);setUpkeepError('');api<{editions:Edition[]}>('/v1/collections/'+selected.address).then(v=>{if(!cancelled)setEditions(v.editions);}).catch(e=>{if(!cancelled)setEditionError(friendlyError(e));});
  if(client&&configured)client.readContract({address:selected.address,abi:nftAbi,functionName:'currentPrice'}).then(v=>{if(!cancelled)setPrice(v);}).catch(()=>{if(!cancelled)setPriceError('The current mint price could not be read from the contract. Refresh to retry.');});
  api<any>('/v1/upkeep/'+selected.address).then(v=>{if(!cancelled)setUpkeep(v);}).catch(e=>{if(!cancelled)setUpkeepError(friendlyError(e));});return()=>{cancelled=true;};},[selected?.address,client,configured,dataRevision]);
 useEffect(()=>{let cancelled=false;setCreationFee(undefined);if(client&&config&&configured)Promise.all([client.readContract({address:config.deployment.factory,abi:factoryAbi,functionName:'creationFee'}),client.readContract({address:config.deployment.upic,abi:tokenAbi,functionName:'decimals'})]).then(([fee,decimals])=>{if(!cancelled){setCreationFee(fee);setTokenDecimals(decimals);}}).catch(()=>{});return()=>{cancelled=true;};},[client,config,configured,dataRevision]);
 useEffect(()=>{let cancelled=false;setBalances(undefined);setBalanceError('');if(wallet&&client&&config&&configured){void loadOwned(wallet);Promise.all([client.getBalance({address:wallet}),client.readContract({address:config.deployment.upic,abi:tokenAbi,functionName:'balanceOf',args:[wallet]}),client.readContract({address:config.deployment.vault,abi:vaultAbi,functionName:'claimable',args:[wallet]})]).then(([eth,upic,revenue])=>{if(!cancelled)setBalances({eth,upic,revenue});}).catch(e=>{if(!cancelled)setBalanceError(friendlyError(e));});}return()=>{cancelled=true;};},[wallet,client,config,configured,dataRevision]);
 function clearWallet(){authEpoch.current++;suppressSession(true);walletRef.current=undefined;setWallet(undefined);setOwned([]);setBalances(undefined);setIntent(undefined);setForm(undefined);}
 useEffect(()=>{if(!config||!configured)return;let disposed=false;const epoch=authEpoch.current;const provider=window.ethereum as (NonNullable<Window['ethereum']>&{on?:(event:string,listener:(...args:any[])=>void)=>void;removeListener?:(event:string,listener:(...args:any[])=>void)=>void})|undefined;
  async function restore(){if(!provider||sessionSuppressed())return;try{const [session,accounts,chain]=await Promise.all([api<{wallet:Address|null}>('/v1/auth/session'),provider.request({method:'eth_accounts'}),provider.request({method:'eth_chainId'})]);if(!disposed&&epoch===authEpoch.current&&session.wallet&&same(accounts[0],session.wallet)&&Number(chain)===config!.deployment.chainId){walletRef.current=session.wallet;setWallet(session.wallet);}}catch{/* A missing session is normal before sign-in. */}}
  void restore();const changed=()=>{clearWallet();authInvalidation.current=authInvalidation.current.catch(()=>{}).then(()=>api('/v1/auth/logout',{})).catch(()=>{});report('Wallet account or network changed. Connect again to sign in to staging.');};provider?.on?.('accountsChanged',changed);provider?.on?.('chainChanged',changed);provider?.on?.('disconnect',changed);return()=>{disposed=true;provider?.removeListener?.('accountsChanged',changed);provider?.removeListener?.('chainChanged',changed);provider?.removeListener?.('disconnect',changed);};},[config,configured]);
 useEffect(()=>{if(!intent?.intentId||['expired','complete','failed'].includes(intent.state)||(intent.state==='ready'&&intent.payload&&intent.signature))return;let cancelled=false;const poll=()=>api<Intent>('/v1/intents/'+intent.intentId).then(v=>{if(!cancelled)setIntent(old=>old&&old.intentId===intent.intentId?{...old,...v,intentId:v.id||old.intentId}:old);}).catch(e=>{if(!cancelled)report(friendlyError(e),'error');});void poll();const timer=setInterval(poll,5000);return()=>{cancelled=true;clearInterval(timer);};},[intent?.intentId,intent?.state,Boolean(intent?.payload)]);
 useEffect(()=>{if(intent?.state!=='ready')return;const timer=setInterval(()=>setTick(t=>t+1),1000);return()=>clearInterval(timer);},[intent?.state]);
 const expired=Boolean(intent?.expires_at&&Date.parse(intent.expires_at)<=Date.now());void tick;
 async function action(fn:()=>Promise<void>){setBusy(true);setTxHash(undefined);report('');try{await fn();}catch(e){report(friendlyError(e),'error');}finally{setBusy(false);}}
 async function walletClient(){if(!window.ethereum)throw Error('Open staging in an EVM wallet browser or enable an EVM wallet extension to connect.');if(!config||!net||!configured)throw Error('Staging contracts are not configured for a supported test network.');
  await window.ethereum.request({method:'eth_requestAccounts'});
  try{await window.ethereum.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x'+config.deployment.chainId.toString(16)}]});}catch(e:any){if(e?.code===4001)throw Error('Network switch was declined. No transaction was sent.');if(e?.code!==4902&&e?.data?.originalError?.code!==4902)throw e;await window.ethereum.request({method:'wallet_addEthereumChain',params:[{chainId:'0x'+config.deployment.chainId.toString(16),chainName:net.name,nativeCurrency:{name:'ETH',symbol:'ETH',decimals:18},rpcUrls:[net.rpc],...(net.explorer?{blockExplorerUrls:[net.explorer]}:{})}]});await window.ethereum.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x'+config.deployment.chainId.toString(16)}]});}
  const chain=await window.ethereum.request({method:'eth_chainId'});if(Number(chain)!==config.deployment.chainId)throw Error('Switch your wallet to '+net.name+' and try again.');return createWalletClient({chain:targetChain,transport:custom(window.ethereum)});}
 async function connect(){const w=await walletClient(),[account]=await w.requestAddresses();if(!account)throw Error('No wallet account was selected.');for(;;){const pending=authInvalidation.current;await pending.catch(()=>{});if(pending===authInvalidation.current)break;}const epoch=authEpoch.current;report('Sign the sign-in message in your wallet. This does not spend tokens.');const {message}=await api<{message:string}>('/v1/auth/challenge',{wallet:account});const signature=await w.signMessage({account,message});if(epoch!==authEpoch.current)throw Error('The wallet changed during sign-in. Please connect again.');await api('/v1/auth/login',{message,signature});const accounts=await window.ethereum!.request({method:'eth_accounts'});const chain=await window.ethereum!.request({method:'eth_chainId'});if(epoch!==authEpoch.current||!same(accounts[0],account)||Number(chain)!==config!.deployment.chainId){await api('/v1/auth/logout',{});throw Error('The wallet changed during sign-in. Please connect again.');}suppressSession(false);walletRef.current=account;setWallet(account);report('Connected to '+net?.name+'. Your test wallet is ready.','success');}
 async function logout(){clearWallet();try{const pending=authInvalidation.current.catch(()=>{}).then(()=>api('/v1/auth/logout',{}));authInvalidation.current=pending.catch(()=>{});await pending;report('Signed out of staging. Your wallet extension remains under your control.','success');}catch{report('Signed out on this device. The service could not confirm session removal; reconnect to start a new session.','info');}}
 async function ensureSigner(){const account=walletRef.current;if(!account)throw Error('Connect your wallet to continue.');const w=await walletClient();const [active]=await w.getAddresses();if(!same(active,account)||!same(walletRef.current,account))throw Error('Your active wallet changed. Connect again before continuing.');return {w,account,epoch:authEpoch.current};}
 async function transaction(address:Address,abi:any,functionName:string,args:any[]=[],value=0n){if(!client||!configured)throw Error('Staging contracts are not configured.');const {w,account,epoch}=await ensureSigner();report('Checking the transaction before requesting your signature…');await client.simulateContract({account,address,abi,functionName,args,value}).catch((e:any)=>{throw Error(e?.shortMessage||'This transaction would fail. Nothing was submitted.');});const gas=await client.estimateContractGas({account,address,abi,functionName,args,value});const [active]=await w.getAddresses();const chainId=await w.getChainId();if(!same(active,account)||!same(walletRef.current,account)||epoch!==authEpoch.current||chainId!==targetChain?.id)throw Error('Your active wallet or network changed. Connect again.');report('Confirm the test transaction in your wallet…');const hash=await w.writeContract({account,chain:targetChain,address,abi,functionName,args,value,gas:gas*12n/10n});setTxHash(hash);report('Transaction submitted. Waiting for confirmation…');const receipt=await client.waitForTransactionReceipt({hash});if(receipt.status!=='success')throw Error('The transaction reverted. Check its receipt for details.');report('Transaction confirmed. Indexed collection data may take a moment to update.','success');await refresh();}
 async function openListedEdition(order:Order){const result=await api<{editions:Edition[]}>('/v1/collections/'+order.collection);const found=result.editions.find(e=>e.edition===order.edition);if(!found)throw Error('This edition is not indexed yet. Refresh in a moment.');openEdition(found);}
 async function prepareMint(asset:Asset|undefined,creation:boolean){if(!asset)throw Error('The source asset is not available. Refresh the collection and try again.');if(!wallet)throw Error('Connect your wallet to prepare an artwork.');const {account,epoch}=await ensureSigner();const result=await api<Intent>('/v1/prepare/'+(creation?'create':'mint'),{assetKey:asset.asset_key});if(epoch!==authEpoch.current||!same(walletRef.current,account))throw Error('Your wallet changed during preparation. Connect again to continue.');setIntent({...result,intentId:result.intentId||result.id,assetKey:asset.asset_key,creation});report(result.state==='verification-pending'?'Blockchain verification is queued. Use “Check preparation” after it completes.':'Artwork preparation has started. You can keep browsing while the renderer works.');}
 async function mint(){if(!intent||intent.state!=='ready'||!intent.payload||!intent.signature||!config||expired)throw Error('Prepare this artwork again before signing. Its authorization is not ready or has expired.');await ensureSigner();const p=intent.payload;
  if(intent.collection){const current=await client!.readContract({address:intent.collection,abi:nftAbi,functionName:'currentPrice'});await transaction(intent.collection,nftAbi,'mint',[{...p,nonce:BigInt(p.nonce),deadline:BigInt(p.deadline)},intent.signature],current);}
  else{const fee=await client!.readContract({address:config.deployment.factory,abi:factoryAbi,functionName:'creationFee'}),allowance=await client!.readContract({address:config.deployment.upic,abi:tokenAbi,functionName:'allowance',args:[wallet!,config.deployment.factory]});if(allowance<fee)await transaction(config.deployment.upic,tokenAbi,'approve',[config.deployment.factory,fee]);await transaction(config.deployment.factory,factoryAbi,'create',[{...p,sourceChain:BigInt(p.sourceChain),cap:BigInt(p.cap),nonce:BigInt(p.nonce),deadline:BigInt(p.deadline)},intent.signature]);}setIntent(undefined);}
 async function submitForm(value:string){if(!form||!config)return;if(form.kind==='upkeep')await transaction(config.deployment.vault,vaultAbi,'fundMaintenance',[form.collection.address],amount(value));else if(form.kind==='transfer'){if(!isAddress(value)||value.toLowerCase()===zeroAddress)throw Error('Enter a complete EVM wallet address beginning with 0x.');if(same(value,wallet))throw Error('Choose a different receiving wallet.');await transaction(form.edition.collection,nftAbi,'safeTransferFrom',[wallet,value,BigInt(form.edition.edition)]);}else{const edition=form.edition,price=amount(value);await transaction(edition.collection,nftAbi,'approve',[config.deployment.marketplace,BigInt(edition.edition)]);const {w,account}=await ensureSigner();const ownershipNonce=await client!.readContract({address:edition.collection,abi:nftAbi,functionName:'transferNonce',args:[BigInt(edition.edition)]});const nonce=BigInt('0x'+crypto.randomUUID().replace(/-/g,''));const order={seller:account,collection:edition.collection,tokenId:BigInt(edition.edition),price,expiry:BigInt(Math.floor(Date.now()/1000)+86400),nonce,ownershipNonce};report('Sign the listing in your wallet. It expires after 24 hours.');const signature=await w.signTypedData({account,domain:domain(DOMAINS.marketplace,config.deployment.chainId,config.deployment.marketplace),types:orderTypes,primaryType:'Order',message:order});if(!same(walletRef.current,account))throw Error('The wallet changed while signing. Reconnect before listing.');await api('/v1/orders',{order:JSON.parse(JSON.stringify(order,(_,v)=>typeof v==='bigint'?v.toString():v)),signature});await refresh();report('Listing published for 24 hours.','success');}setForm(undefined);}
 const media=(uri:string)=>uri.startsWith('ipfs://')?(config?.gateway||'https://ipfs.io').replace(/\/$/,'')+'/ipfs/'+uri.slice(7):/^https?:\/\//.test(uri)?uri:'';
